from collections import deque,Counter

def comps(grid, pred=lambda v:v!=0, connectivity=4):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
        if (r,c) in seen or not pred(grid[r][c]): continue
        q=[(r,c)]; seen.add((r,c)); pix=[]
        for x,y in q:
          pix.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(x+dx,y+dy)
            if 0<=p[0]<R and 0<=p[1]<C and p not in seen and pred(grid[p[0]][p[1]]): seen.add(p); q.append(p)
        out.append(pix)
    return out

