def dfs(covered,used,chosen,limit=3):
    if len(solutions)>=limit:return
    if len(covered)==len(mask):
        if len(used)==len(placements): solutions.append(chosen.copy())
        return
    unc=mask-covered
    # choose cell with fewest viable placements
    best=None; opts=None
    for cell in unc:
        cand=[pl for pl in cover_by_cell[cell] if pl[0] not in used and not(pl[3]&covered)]
        if opts is None or len(cand)<len(opts): best,opts=cell,cand
        if len(opts)==0: return
        if len(opts)==1: break
